```
public class DuplicateResourceDetector extends ResourceXmlDetector {
    private static final Implementation IMPLEMENTATION = new Implementation(
            DuplicateResourceDetector.class,
            Scope.RESOURCE_FILE_SCOPE);
    public static final Issue ISSUE = Issue.create(
            "DuplicateDefinition",
            "Duplicate definitions of resources",
            "...",
            Category.CORRECTNESS,
            6,
            Severity.WARNING,
            IMPLEMENTATION);

    private Map<String, List<Location>> mLocations;

    @Override
    public void beforeCheckProject(Context context) {
        mLocations = new HashMap<>();
    }

    @Override
    public Collection<String> getApplicableElements() {
        return XmlScannerConstants.ALL;
    }

    @Override
    public void visitElement(XmlContext context, Element element) {
        ResourceFolderType folderType = context.getResourceFolderType();
        if (folderType == null) return;
        Node parent = element.getParentNode();
        if (parent == null) return;
        if (folderType != ResourceFolderType.VALUES) {
            if (parent.getNodeType() == Node.DOCUMENT_NODE) {
                File file = context.file; // or getFile
                String name = file.getName();
                int dot = name.lastIndexOf('.');
                if (dot != -1) name = name.substring(0, dot);
                String type = folderType.name().toLowerCase(Locale.US);
                add(context, file.getParentFile(), type, name, context.getLocation(element));
            }
            return;
        }
        if (!"resources".equals(parent.getNodeName())) return;
        String tagName = element.getTagName();
        ResourceType type = ResourceType.fromXmlTag(element);
        if (type == null) {
            String itemType = element.getAttribute("type");
            if (!itemType.isEmpty()) {
                type = ResourceType.fromName(itemType);
            }
        }
        if (type == null) return;
        String name = element.getAttribute("name");
        if (name.isEmpty()) return;
        add(context, context.getFile().getParentFile(), type.getName(), name, context.getLocation(element));
    }

    private void add(XmlContext context, File folder, String type, String name, Location location) {
        String key = folder.getPath() + "/" + type + "/" + name;
        List<Location> list = mLocations.get(key);
        if (list == null) {
            list = new ArrayList<>();
            mLocations.put(key, list);
        } else {
            Location first = list.get(0);
            String message = String.format(
                "Duplicate resource %s/%s (already defined in %s)",
                type, name, first.getFile().getName());
            context.report(ISSUE, location, message);
        }
        list.add(location);
    }
}
```

